BEGIN;
CREATE TABLE IF NOT EXISTS "Propietarios" (
 "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 "Nombre" varchar(100) NOT NULL,
 "Dni" varchar(8) NOT NULL UNIQUE,
 "Telefono" varchar(20) NOT NULL);
CREATE TABLE IF NOT EXISTS "Mascotas" (
 "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 "Nombre" varchar(80) NOT NULL,
 "Especie" varchar(40) NOT NULL,
 "Edad" integer NOT NULL CHECK ("Edad" BETWEEN 0 AND 40),
 "PropietarioId" integer NOT NULL REFERENCES "Propietarios"("Id") ON DELETE RESTRICT);
CREATE INDEX IF NOT EXISTS "IX_Mascotas_PropietarioId" ON "Mascotas"("PropietarioId");
CREATE TABLE IF NOT EXISTS "Usuarios" (
 "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 "Correo" varchar(254) NOT NULL UNIQUE CHECK ("Correo" = lower(trim("Correo"))),
 "ClaveHash" varchar(100) NOT NULL,
 "Rol" varchar(30) NOT NULL CHECK ("Rol" IN ('Recepcionista', 'Veterinario')));
INSERT INTO "Propietarios" ("Nombre", "Dni", "Telefono") VALUES
 ('Ana Torres','12345678','987654321'), ('Luis Rojas','87654321','912345678') ON CONFLICT ("Dni") DO NOTHING;
INSERT INTO "Mascotas" ("Nombre", "Especie", "Edad", "PropietarioId")
 SELECT 'Luna','Perro',3,"Id" FROM "Propietarios" WHERE "Dni"='12345678'
 AND NOT EXISTS (SELECT 1 FROM "Mascotas" WHERE "Nombre"='Luna');
INSERT INTO "Usuarios" ("Correo", "ClaveHash", "Rol") VALUES ('recepcionista@veterinaria.test', '$2b$12$x3bPAoF/zly3KpXJMk15WO52E52Lo8JUv5.uT0u7cdbIvfn8MEol2', 'Recepcionista') ON CONFLICT ("Correo") DO NOTHING;
INSERT INTO "Usuarios" ("Correo", "ClaveHash", "Rol") VALUES ('veterinario@veterinaria.test', '$2b$12$uYJuxdEz0veKLBQpgORYuelTqu5862mmucMZaQ.htq7ZffVEsHWaW', 'Veterinario') ON CONFLICT ("Correo") DO NOTHING;
COMMIT;
